using Astrea;
using UnityEngine;

public static class StringExtensions
{
	public static string ConcatArray(this string[] array)
	{
		string text = "";
		for (int i = 0; i < array.Length; i++)
		{
			text = text + "\n" + array[i];
		}
		return text;
	}

	public static string Color(this string s, Color c)
	{
		string text = ColorUtility.ToHtmlStringRGBA(c);
		return "<color=#" + text + ">" + s + "</color>";
	}

	public static string Bold(this string s)
	{
		return "<b>" + s + "</b>";
	}

	public static string Italic(this string s)
	{
		return "<i>" + s + "</i>";
	}

	public static string UppercaseFirst(this string s)
	{
		if (string.IsNullOrEmpty(s))
		{
			return string.Empty;
		}
		char[] array = s.ToCharArray();
		array[0] = char.ToUpper(array[0]);
		return new string(array);
	}

	public static string LowercaseFirst(this string str)
	{
		if (string.IsNullOrEmpty(str) || char.IsLower(str[0]))
		{
			return str;
		}
		return char.ToLower(str[0]) + str.Substring(1);
	}

	public static string RemoveLast(this string str)
	{
		return str.Remove(str.Length - 1);
	}

	public static string GetLocalizedString(this string str)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(str);
	}

	public static string GetSpriteText(this string spriteName)
	{
		return $"<sprite name=\"{spriteName}\">";
	}
}
